UPDATE course_materials
   SET original_removed_at = #{now}, original_removed_reason = #{reason}
 WHERE material_id = #{materialId} AND user_id = #{userId}
   AND origin = 'CONSULT_PHOTO' AND original_removed_at IS NULL

UPDATE course_materials
   SET original_removed_at = #{now}, original_removed_reason = 'EXPIRED'
 WHERE origin = 'CONSULT_PHOTO' AND original_removed_at IS NULL
   AND original_expires_at IS NOT NULL AND original_expires_at <= #{now}
 ORDER BY material_id
 LIMIT #{limit}
